1	-- 软件制品依赖锁定：H2（MODE=MySQL）建表脚本，仅在 JVM 生命周期内保留数据。
2	
3	CREATE TABLE IF NOT EXISTS repository_state (
4	    id      BIGINT       NOT NULL PRIMARY KEY,
5	    version BIGINT       NOT NULL
6	);
7	COMMENT ON TABLE repository_state IS '单行表：仓库全局版本号，制品登记或撤回时加一';
8	COMMENT ON COLUMN repository_state.version IS '仓库版本号（无符号长整型语义，初始为 0）';
9	
10	CREATE TABLE IF NOT EXISTS artifact (
11	    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
12	    name       VARCHAR(128) NOT NULL,
13	    version    INT          NOT NULL,
14	    withdrawn  TINYINT      NOT NULL DEFAULT 0,
15	    created_at TIMESTAMP(6) NOT NULL
16	);
17	COMMENT ON TABLE artifact IS '软件制品版本，name 与 version 联合唯一，撤回不删除';
18	COMMENT ON COLUMN artifact.name IS '制品名称';
19	COMMENT ON COLUMN artifact.version IS '制品版本号，正整数';
20	COMMENT ON COLUMN artifact.withdrawn IS '撤回状态：0=有效，1=已撤回（记录保留）';
21	COMMENT ON COLUMN artifact.created_at IS '登记时间，UTC 时间戳';
22	
23	CREATE UNIQUE INDEX IF NOT EXISTS uk_artifact_name_version ON artifact (name, version);
24	CREATE INDEX IF NOT EXISTS idx_artifact_name ON artifact (name);
25	
26	CREATE TABLE IF NOT EXISTS artifact_dependency (
27	    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
28	    artifact_id     BIGINT       NOT NULL,
29	    name            VARCHAR(128) NOT NULL,
30	    minimum_version INT          NOT NULL,
31	    maximum_version INT          NOT NULL,
32	    CONSTRAINT fk_dep_artifact FOREIGN KEY (artifact_id) REFERENCES artifact (id)
33	);
34	COMMENT ON TABLE artifact_dependency IS '制品声明的依赖区间（闭区间），登记后不可改';
35	COMMENT ON COLUMN artifact_dependency.artifact_id IS '所属制品版本 ID';
36	COMMENT ON COLUMN artifact_dependency.name IS '依赖制品名称，同一制品内唯一';
37	COMMENT ON COLUMN artifact_dependency.minimum_version IS '依赖最低版本（含），正整数';
38	COMMENT ON COLUMN artifact_dependency.maximum_version IS '依赖最高版本（含），正整数';
39	
40	CREATE UNIQUE INDEX IF NOT EXISTS uk_dep_artifact_name ON artifact_dependency (artifact_id, name);
41	
42	CREATE TABLE IF NOT EXISTS lock_file (
43	    id                 BIGINT AUTO_INCREMENT PRIMARY KEY,
44	    root_name          VARCHAR(128) NOT NULL,
45	    root_version       INT          NOT NULL,
46	    repository_version BIGINT       NOT NULL,
47	    request_id         VARCHAR(64)  NOT NULL,
48	    created_at         TIMESTAMP(6) NOT NULL
49	);
50	COMMENT ON TABLE lock_file IS '锁定文件：一次成功锁定的根、精确依赖集合及读取时的仓库版本';
51	COMMENT ON COLUMN lock_file.root_name IS '根制品名称（精确版本，锁定时固定）';
52	COMMENT ON COLUMN lock_file.root_version IS '根制品版本号，正整数';
53	COMMENT ON COLUMN lock_file.repository_version IS '锁定时读取的仓库版本号';
54	COMMENT ON COLUMN lock_file.request_id IS '触发锁定的全局唯一请求 ID';
55	COMMENT ON COLUMN lock_file.created_at IS '锁定生成时间，UTC 时间戳';
56	
57	CREATE UNIQUE INDEX IF NOT EXISTS uk_lock_request ON lock_file (request_id);
58	CREATE INDEX IF NOT EXISTS idx_lock_root ON lock_file (root_name, root_version);
59	
60	CREATE TABLE IF NOT EXISTS lock_file_entry (
61	    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
62	    lock_file_id BIGINT       NOT NULL,
63	    name         VARCHAR(128) NOT NULL,
64	    version      INT          NOT NULL,
65	    CONSTRAINT fk_entry_lock FOREIGN KEY (lock_file_id) REFERENCES lock_file (id)
66	);
67	COMMENT ON TABLE lock_file_entry IS '锁文件中的精确制品版本，每个名称仅一个版本';
68	COMMENT ON COLUMN lock_file_entry.lock_file_id IS '所属锁文件 ID';
69	COMMENT ON COLUMN lock_file_entry.name IS '被锁定制品名称';
70	COMMENT ON COLUMN lock_file_entry.version IS '被锁定的精确版本号，正整数';
71	
72	CREATE UNIQUE INDEX IF NOT EXISTS uk_entry_lock_name ON lock_file_entry (lock_file_id, name);
73	
74	CREATE TABLE IF NOT EXISTS idempotent_request (
75	    request_id     VARCHAR(64)  NOT NULL PRIMARY KEY,
76	    operation      VARCHAR(32)  NOT NULL,
77	    request_hash   VARCHAR(64)  NOT NULL,
78	    http_status    INT          NOT NULL,
79	    response_json  CHARACTER LARGE OBJECT NOT NULL,
80	    created_at     TIMESTAMP(6) NOT NULL
81	);
82	COMMENT ON TABLE idempotent_request IS '写操作幂等记录，仅保存成功请求；失败不占键';
83	COMMENT ON COLUMN idempotent_request.request_id IS '客户端提供的全局唯一请求 ID';
84	COMMENT ON COLUMN idempotent_request.operation IS '操作类型：REGISTER_ARTIFACT/WITHDRAW_ARTIFACT/CREATE_LOCK';
