82	    @Test
83	    void lockProducesSortedEntriesAndPersistsRepositoryVersion() {
84	        // app:1 -> lib[1,2] 且 util[1,1]；lib2/lib1 均在，取高版本 lib2。
85	        service.registerArtifact(requestId(),
86	                artifact("app", 1, dep("util", 1, 1), dep("lib", 1, 2)));
87	        service.registerArtifact(requestId(), artifact("lib", 2));
88	        service.registerArtifact(requestId(), artifact("lib", 1));
89	        service.registerArtifact(requestId(), artifact("util", 1));
90	
91	        LockFileResponse lock = service.createLock(requestId(), new LockRequest("app", 1, 4L));
92	
93	        assertThat(lock.repositoryVersion()).isEqualTo(4L);
94	        assertThat(lock.rootName()).isEqualTo("app");
95	        assertThat(lock.rootVersion()).isEqualTo(1);
96	        assertThat(lock.entries()).extracting("name", "version")
97	                .containsExactly(tuple("app", 1), tuple("lib", 2), tuple("util", 1));
98	
99	        // 历史查询：列表与单查一致，条目按名称升序。
100	        List<LockFileResponse> locks = service.listLocks();
101	        assertThat(locks).hasSize(1);
102	        assertThat(service.getLock(lock.id()).entries()).isEqualTo(lock.entries());
103	    }
