package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 摘要登记请求：为制品版本登记内容校验摘要。
 *
 * <p>摘要格式为 {@code sha256:} 前缀加 64 位十六进制字符（大小写不敏感，
 * 存储与比较统一规范化为小写）。
 */
public record RegisterChecksumRequest(@NotBlank String checksum) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 见证提交请求：发布角色对制品版本已登记摘要的见证。
 *
 * @param role     发布角色标识（操作者），同一版本内同一角色仅允许一条有效见证
 * @param checksum 见证的内容校验摘要，必须与已登记摘要一致（规范化后比较）
 */
public record AttestationRequest(
        @NotBlank String role,
        @NotBlank String checksum) {
}

package com.example.starter.api.dto;

import java.time.Instant;

/**
 * 摘要登记结果视图。
 *
 * @param checksum           规范化后的内容校验摘要（小写）
 * @param attestationVersion 该制品版本当前的见证版本号（每次见证登记或撤销加一）
 * @param registeredAt       摘要登记时间，UTC
 */
public record ChecksumResponse(
        String name,
        int version,
        String checksum,
        int attestationVersion,
        Instant registeredAt) {
}

package com.example.starter.api.dto;

import java.time.Instant;

/**
 * 见证提交/撤销结果视图。
 *
 * @param revoked            是否已撤销：true=已撤销（记录保留，不再计入有效见证）
 * @param attestationVersion 本次操作后的见证版本号
 * @param createdAt          见证首次提交时间，UTC
 * @param revokedAt          撤销时间，UTC；未撤销为 null
 */
public record AttestationResponse(
        String name,
        int version,
        String role,
        String checksum,
        boolean revoked,
        int attestationVersion,
        Instant createdAt,
        Instant revokedAt) {
}

package com.example.starter.api.dto;

import java.time.Instant;

/**
 * 单条见证记录视图（含已撤销的历史见证）。
 *
 * @param revoked   是否已撤销
 * @param createdAt 见证首次提交时间，UTC
 * @param revokedAt 撤销时间，UTC；未撤销为 null
 */
public record AttestationView(
        String role,
        String checksum,
        boolean revoked,
        Instant createdAt,
        Instant revokedAt) {
}

